import{_ as o,o as a,c as e,a2 as r}from"./chunks/framework.C4u7U0Dw.js";const _=JSON.parse('{"title":"第 2 章 第一次对话：把需求讲清楚（易懂版）","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第2章 第一次对话：把需求讲清楚（易懂版）.md","filePath":"easy/第2章 第一次对话：把需求讲清楚（易懂版）.md"}'),l={name:"easy/第2章 第一次对话：把需求讲清楚（易懂版）.md"};function s(d,t,n,i,h,c){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="第-2-章-第一次对话-把需求讲清楚-易懂版" tabindex="-1">第 2 章 第一次对话：把需求讲清楚（易懂版） <a class="header-anchor" href="#第-2-章-第一次对话-把需求讲清楚-易懂版" aria-label="Permalink to &quot;第 2 章 第一次对话：把需求讲清楚（易懂版）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📖 想读完整版？</p><p>这页是<strong>易懂版</strong>，用大白话讲重点。想系统学习，请读 [第 2 章 第一次对话：把需求讲清楚（完整版）](../../bluebook/第一篇 使用手册：先把我用起来/第 2 章 第一次对话：把需求讲清楚.md)。</p></div><h2 id="这章讲什么-一句话" tabindex="-1">这章讲什么（一句话） <a class="header-anchor" href="#这章讲什么-一句话" aria-label="Permalink to &quot;这章讲什么（一句话）&quot;">​</a></h2><p><strong>怎么跟 AI 说人话，让它一次就听懂你要啥。</strong></p><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><p>去餐厅点菜：你说&quot;来点吃的&quot;，服务员只能一脸懵。但你说&quot;<strong>一份番茄鸡蛋面，少放盐，不要香菜，打包带走</strong>&quot;——他立刻知道怎么办。</p><p>跟 AI 说话也一样：<strong>说得越具体，做得越对。</strong></p><h2 id="核心就-4-件事-点菜四要素" tabindex="-1">核心就 4 件事（点菜四要素） <a class="header-anchor" href="#核心就-4-件事-点菜四要素" aria-label="Permalink to &quot;核心就 4 件事（点菜四要素）&quot;">​</a></h2><ol><li><strong>要什么</strong>（目标）：最终要一个什么东西？Excel？报告？整理好的文件夹？</li><li><strong>给什么</strong>（背景）：材料在哪？哪些文件相关？前提是什么？</li><li><strong>别踩雷</strong>（约束）：格式要求？不能动哪些文件？时间限制？</li><li><strong>怎么交</strong>（交付形式）：结果放哪、叫什么名、什么格式？</li></ol><h2 id="坏指令-vs-好指令" tabindex="-1">坏指令 vs 好指令 <a class="header-anchor" href="#坏指令-vs-好指令" aria-label="Permalink to &quot;坏指令 vs 好指令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>❌ 坏指令</th><th>✅ 好指令</th></tr></thead><tbody><tr><td>&quot;帮我整理一下&quot;</td><td>&quot;把 <code>销售数据.xlsx</code> 按月份汇总成一张表，放 <code>汇总</code> 文件夹，叫 <code>月度汇总.xlsx</code>&quot;</td></tr><tr><td>&quot;写个方案&quot;</td><td>&quot;写一份 3 页的开店方案：预算 10 万，目标人群是大学生，周五前给我 Word 版&quot;</td></tr><tr><td>&quot;改一下这段&quot;</td><td>&quot;把这段话改得更正式，删掉口语词，保留原意，200 字以内&quot;</td></tr></tbody></table><h2 id="上手小例子" tabindex="-1">上手小例子 <a class="header-anchor" href="#上手小例子" aria-label="Permalink to &quot;上手小例子&quot;">​</a></h2><blockquote><p><strong>指令</strong>：&quot;把 <code>报告初稿.docx</code> 改成一页纸的摘要：开头一段讲结论，中间三条理由，结尾给建议；语气正式；输出到 <code>摘要.docx</code>。&quot;</p><p><strong>你会看到</strong>：我读完原文 → 提炼 → 重写成摘要 → 生成新文件。</p></blockquote><h2 id="别踩的坑" tabindex="-1">别踩的坑 <a class="header-anchor" href="#别踩的坑" aria-label="Permalink to &quot;别踩的坑&quot;">​</a></h2><ul><li>❌ 一次交代三件没关联的事——<strong>一件一件来</strong>，做完一件再下一件；</li><li>❌ 不说背景——&quot;帮我改这段&quot;而我根本不知道这段是给谁看的；</li><li>❌ 不说交付形式——结果给成什么算满意，提前讲清楚。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>好的指令 = 要什么 + 给什么 + 别踩雷 + 怎么交。</strong> 四样说全，一次成功。</p><h2 id="一分钟测试" tabindex="-1">一分钟测试 <a class="header-anchor" href="#一分钟测试" aria-label="Permalink to &quot;一分钟测试&quot;">​</a></h2><p>把你下一个任务写成一句话，检查里面有没有这四样：目标？背景？约束？交付？——<strong>四样齐全再发出去</strong>。</p><p>👉 [下一章：我的工作方式，文件、命令与工具（易懂版）](第3章 我的工作方式：文件、命令与工具（易懂版）.md)</p>',20)])])}const q=o(l,[["render",s]]);export{_ as __pageData,q as default};
